def parser(log: str) -> dict:
    """从 pytest-json-report 输出中解析逐个测试的结果。"""
    import json
    out = {}
    text = log.strip()
    doc = None
    start = text.find("{")
    if start >= 0:
        try:
            doc, _ = json.JSONDecoder().raw_decode(text[start:])
        except Exception:
            doc = None
    if doc is None:
        for line in log.splitlines():
            s = line.strip()
            if s.startswith("{") and '"tests"' in s:
                try:
                    doc = json.loads(s)
                except Exception:
                    continue
                break
    if not doc:
        return out
    for item in doc.get("tests") or []:
        nodeid = item.get("nodeid")
        outcome = (item.get("outcome") or "").lower()
        if not nodeid:
            continue
        if outcome in ("passed", "xpassed"):
            out[nodeid] = "pass"
        elif outcome in ("failed", "error"):
            out[nodeid] = "fail"
        else:
            out[nodeid] = "skip"
    return out
